<?php
declare(strict_types=1); namespace McpEmail\Tools;
use McpEmail\Config;use McpEmail\Mail\ImapClient;use McpEmail\Security\EmailSecurityAnalyzer;use Throwable;
final class ScanMailboxSecurityTool implements ToolInterface
{public function name():string{return 'scan_mailbox_security';}public function definition():array{return ['title'=>'Mailbox veiligheids-scan','description'=>'Scant een begrensde, gepagineerde selectie. Alleen geselecteerde berichten worden volledig gelezen; er volgen geen automatische acties.','inputSchema'=>['type'=>'object','properties'=>['folder'=>['type'=>'string','default'=>'INBOX'],'date_from'=>['type'=>'string','format'=>'date'],'date_to'=>['type'=>'string','format'=>'date'],'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>100,'default'=>25],'offset'=>['type'=>'integer','minimum'=>0,'maximum'=>10000,'default'=>0],'risk_threshold'=>['type'=>'integer','minimum'=>0,'maximum'=>100,'default'=>25],'unread_only'=>['type'=>'boolean'],'include_safe'=>['type'=>'boolean','default'=>false],'sender_domain'=>['type'=>'string'],'has_attachments'=>['type'=>'boolean'],'account'=>['type'=>'string']],'additionalProperties'=>false]];}public function call(array $a):array{$limit=max(1,min(100,(int)($a['limit']??25)));$offset=max(0,(int)($a['offset']??0));$folder=(string)($a['folder']??'INBOX');$parts=[];if(!empty($a['date_from']))$parts['SINCE']=new \DateTimeImmutable((string)$a['date_from']);if(!empty($a['date_to']))$parts['BEFORE']=(new \DateTimeImmutable((string)$a['date_to']))->modify('+1 day');if(!empty($a['unread_only']))$parts['UNSEEN']='';if(!empty($a['sender_domain']))$parts['FROM']=(string)$a['sender_domain'];$criteria=$this->criteria($parts);$c=null;try{$c=ImapClient::connect(Config::getAccount(isset($a['account'])?(string)$a['account']:null),$folder);$all=$c->searchUids($criteria);rsort($all);$page=array_slice($all,$offset,$limit);$counts=['high'=>0,'suspicious'=>0,'attention'=>0,'low'=>0];$items=[];$an=new EmailSecurityAnalyzer();foreach($page as $uid){$m=$c->readMessage($uid);if(!$m)continue;if(array_key_exists('has_attachments',$a)&&((bool)$a['has_attachments']!==($m['attachments']!==[])))continue;$r=$an->analyze($m);$counts[$r['risk_level']]++;if(($r['risk_score']>=(int)($a['risk_threshold']??25))||!empty($a['include_safe']))$items[]=['uid'=>$uid,'from'=>$m['from'],'subject'=>$m['subject'],'date'=>$m['date'],'score'=>$r['risk_score'],'risk_level'=>$r['risk_level'],'top_signals'=>array_slice($r['signals'],0,3)];}return Support::apiSuccess(['scanned'=>array_sum($counts),'counts'=>$counts,'suspicious_emails'=>$items],['limit'=>$limit,'offset'=>$offset,'total'=>count($all),'has_more'=>$offset+$limit<count($all)]);}catch(Throwable){return Support::apiError('SEARCH_FAILED','De mailboxscan kon niet worden uitgevoerd.');}finally{$c?->close();}}
private function criteria(array $parts):string{$tokens=[];foreach($parts as $k=>$v){if($k==='UNSEEN'){$tokens[]='UNSEEN';continue;}$tokens[]=$k.' "'.($v instanceof \DateTimeImmutable?$v->format('d-M-Y'):str_replace(['\\','"'],['\\\\','\\"'],(string)$v)).'"';}return $tokens?implode(' ',$tokens):'ALL';}}
